// Regenerates js/pinterest-data.js from the Pinterest board RSS feed.
//
// Pinterest's board RSS has no CORS headers either (same problem as the
// Hashnode blog feed), so this runs at build time in Node and writes a
// static generated file — see scripts/fetch-blog-posts.js for the same
// pattern. Displaying the resulting i.pinimg.com URLs via <img src> at
// runtime needs no CORS at all, since that's a passive resource load.
//
// Run this whenever new pins are added:
//   node scripts/fetch-pinterest-photos.js

const fs = require('fs');
const path = require('path');

const RSS_URL = 'https://www.pinterest.com/anishshilpakar/daily-snaps.rss';
const PHOTO_COUNT = 10;
const OUTPUT_PATH = path.join(__dirname, '..', 'js', 'pinterest-data.js');

function decodeEntities(str) {
  return str
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&amp;/g, '&');
}

function field(itemBlock, tag) {
  const match = itemBlock.match(new RegExp(`<${tag}>([\\s\\S]*?)</${tag}>`));
  return match ? match[1].trim() : '';
}

async function main() {
  const res = await fetch(RSS_URL);
  if (!res.ok) throw new Error(`Pinterest RSS fetch failed: ${res.status} ${res.statusText}`);
  const xml = await res.text();

  const items = [...xml.matchAll(/<item>([\s\S]*?)<\/item>/g)]
    .map(m => m[1])
    .map(block => {
      const description = decodeEntities(field(block, 'description'));
      const imgMatch = description.match(/<img src="([^"]+)"/);
      return {
        src: imgMatch ? imgMatch[1] : '',
        href: field(block, 'link')
      };
    })
    .filter(photo => photo.src)
    .slice(0, PHOTO_COUNT);

  if (!items.length) throw new Error('No photos found in Pinterest RSS feed');

  const output = `// Generated by scripts/fetch-pinterest-photos.js from ${RSS_URL}
// Do not edit by hand — re-run the script to refresh (see comment there for why).
// Last generated: ${new Date().toISOString()}

const PINTEREST_PHOTOS = ${JSON.stringify(items, null, 2)};
`;

  fs.writeFileSync(OUTPUT_PATH, output);
  console.log(`Wrote ${items.length} photos to ${OUTPUT_PATH}`);
}

main().catch(err => {
  console.error(err.message);
  process.exit(1);
});
